<style>
    /*
		The mark fills whatever box it is given and takes its height from the viewBox.
		`fill` is inherited in SVG, so the unclassed shapes below take their colour from here.
	*/
    svg {
        display: block;
        width: 100%;
        height: auto;
        fill: var(--wa-logo-color, currentColor);
    }

    .disc {
        fill: var(--wa-logo-background, none);
    }

    /* The ring is drawn as a stroke, so it needs the colour naming again */
    .ring {
        fill: none;
        stroke: var(--wa-logo-color, currentColor);
        stroke-width: 30;
        stroke-miterlimit: 10;
    }

    .detail {
        fill: var(--wa-logo-detail, var(--wa-logo-color, currentColor));
    }
</style>
